{
  "status": "awaiting_details_to_finalize",
  "required_details": [
    {
      "field": "Milestones",
      "info_needed": "A list of recent milestones with date and impact (e.g., Milestone name, date, short impact statement).",
      "format_example": "- Milestone name — YYYY-MM-DD — Short impact (e.g., increased user adoption by X%)."
    },
    {
      "field": "Upcoming launches",
      "info_needed": "A list of upcoming launches with target date and brief description.",
      "format_example": "- Launch name — YYYY-MM-DD — Brief description of what changes or value it brings."
    },
    {
      "field": "CTA details",
      "info_needed": "What action should employees take, where to review the relevant doc/link, and the deadline.",
      "format_example": "- Action: [what to do]; Link/Document: [URL or path]; Deadline: YYYY-MM-DD."
    },
    {
      "field": "Tone and sign-off",
      "info_needed": "Confirm tone (friendly) and preferred sign-off (e.g., Communications Team)."
    },
    {
      "field": "Word count target",
      "info_needed": "Confirm final word count (default ~170 words)."
    }
  ],
  "notes": [
    "You indicated a friendly tone and want sections for Milestones and Upcoming launches with a CTA.",
    "I will generate a complete 150-200 word internal update once you provide the data for the fields above."
  ],
  "next_step": "Please provide the details in the formats above (you can paste bulleted lists). If you’d like, you can also just paste your data as simple bullets and I’ll format it accordingly.",
  "example_input_format": {
    "Milestones": [
      "Q2 product refresh — 2026-03-15 — Improved onboarding flow, reduced time-to-first-value by 20%"
    ],
    "Upcoming launches": [
      "New analytics dashboard — 2026-04-01 — Self-serve insights for teams"
    ],
    "CTA_details": [
      "Review the launch readiness doc; Link: http://intranet/link; Deadline: 2026-03-25"
    ],
    "Tone_and_signoff": {
      "tone": "friendly",
      "sign_off": "Communications Team"
    },
    "Word_count_target": 170
  }
}

